import sys

def main():
    line = sys.stdin.read().strip()
    if not line:
        return
    parts = list(map(int, line.split()))
    if len(parts) != 3:
        return
    a, b, c = parts

    if a % 2 == b % 2 == c % 2:
        print(-1)
    else:
        total = a + b + c
        mx = max(a, b, c)
        print(total - mx)

if __name__ == "__main__":
    main()
